#!/usr/bin/env bash
# Build what actually SHIPS, on the MSRV that is actually DECLARED.
#
# D-010 says the crate builds on 1.65 and the MSRV CI job proved it -- against
# the repo. Consumers do not get the repo. `cargo package` writes its own
# Cargo.lock into the tarball, generated by whatever toolchain publishes, so
# the artifact and the repo can disagree. They did: `linq_rs 0.2.0` packaged a
# lockfile at format v4 against `rust-version = "1.65"`, and
#
#   lock file version `4` was found, but this version of Cargo does not
#   understand this lock file
#
# on 1.75 -- let alone 1.65. Every existing check passed, because not one of
# them looked inside the tarball. See DECISIONS.md D-023.
#
# Usage: msrv-tarball.sh [MSRV]     (default: the rust-version in Cargo.toml)
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$ROOT"

MSRV="${1:-$(awk -F'"' '/^rust-version/ {print $2; exit}' Cargo.toml)}"
[ -n "$MSRV" ] || { echo "FAIL: could not read rust-version from Cargo.toml"; exit 1; }
# `rustup run 1.65` resolves to a toolchain named 1.65; installs are 1.65.0.
case "$MSRV" in *.*.*) MSRV_TC="$MSRV" ;; *) MSRV_TC="${MSRV}.0" ;; esac

# v3 is understood by Cargo 1.53+. Anything above that must be justified against
# the declared floor, not against whatever the publisher happens to run.
MAX_LOCKFILE_VERSION=3

echo "=== declared MSRV: ${MSRV} (toolchain ${MSRV_TC}) ==="
rustup toolchain install "$MSRV_TC" --profile minimal >/dev/null 2>&1 || true
rustup run "$MSRV_TC" rustc --version \
  || { echo "FAIL: no ${MSRV_TC} toolchain available"; exit 1; }

# Package the way a publisher does -- with stable, not with the MSRV. Packaging
# on the MSRV would generate a lockfile the MSRV can obviously read, which is
# exactly the tautology that let the defect through.
echo
echo "=== packaging with stable (as a real publish does) ==="
rustup toolchain install stable --profile minimal >/dev/null 2>&1 || true
rustup run stable cargo package --workspace --allow-dirty 2>&1 | grep -E "Packaged|error"

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
for c in target/package/*.crate; do tar -xzf "$c" -C "$WORK"; done

fail=0
echo
for d in "$WORK"/*/; do
  pkg="$(basename "$d")"
  lock="${d}Cargo.lock"
  [ -f "$lock" ] || { echo "FAIL: ${pkg} ships no Cargo.lock"; fail=1; continue; }
  ver="$(awk -F'= *' '/^version *=/ {gsub(/[^0-9]/,"",$2); print $2; exit}' "$lock")"
  echo "=== ${pkg}: lockfile v${ver} ==="
  if [ "${ver:-99}" -gt "$MAX_LOCKFILE_VERSION" ]; then
    echo "FAIL: ${pkg} ships lockfile v${ver}; Cargo ${MSRV} cannot parse above v${MAX_LOCKFILE_VERSION}"
    fail=1
    continue
  fi

  # linq_rs_sql dev-depends on `linq_rs = "0.2"`, which is not on crates.io
  # until linq_rs publishes. Point it at the sibling TARBALL -- not at the
  # working tree, so this still tests the packaged artifact.
  if grep -q '^name = "linq_rs_sql"' "${d}Cargo.toml"; then
    sibling="$(ls -d "$WORK"/linq_rs-*/ 2>/dev/null | head -1)"
    [ -n "$sibling" ] || { echo "FAIL: no linq_rs tarball to patch against"; fail=1; continue; }
    printf '\n[patch.crates-io]\nlinq_rs = { path = "%s" }\n' "${sibling%/}" >> "${d}Cargo.toml"
  fi

  if (cd "$d" && rustup run "$MSRV_TC" cargo build --lib --offline 2>&1 | tail -3); then
    echo "  builds on ${MSRV_TC}"
  else
    echo "FAIL: ${pkg} does not build on ${MSRV_TC}"
    fail=1
  fi
done

echo
if [ "$fail" -ne 0 ]; then echo "MSRV tarball gate FAILED"; exit 1; fi
echo "PASS: every published tarball builds on ${MSRV_TC}"
